// \u8CC7\u6599\u4E00\u6A23\u662F\u4E00\u5343\u842C\u500B 0~1 \u7684\u4E82\u6578\uFF1Aarr = [0.42, 0.99, 0.003, ...]
// \u624B\u5BEB for
for (let i = 0; i < arr.length; i++) { const y = arr[i] * 2; if (y > 1) s += y; }
// \u93C8\u5F0F:map \u548C filter \u5404\u7522\u751F\u4E00\u500B\u4E00\u5343\u842C\u7B46\u7684\u4E2D\u9593\u9663\u5217
arr.map((x) => x * 2).filter((y) => y > 1).reduce((a, b) => a + b, 0);
